// entity_type конфигурационных сущностей в config.changes (HLD §16,
// data_infrastructure_spec.md §1.1, §1.9a-c).
type ConfigEntityType int32

const (
	ConfigEntityType_CONFIG_ENTITY_TYPE_UNSPECIFIED        ConfigEntityType = 0
	ConfigEntityType_CONFIG_ENTITY_TYPE_PIPELINE           ConfigEntityType = 1
	ConfigEntityType_CONFIG_ENTITY_TYPE_POLICY_RULESET     ConfigEntityType = 2
	ConfigEntityType_CONFIG_ENTITY_TYPE_POLICY_TEMPLATE    ConfigEntityType = 3
	ConfigEntityType_CONFIG_ENTITY_TYPE_BILLING_TARIFF     ConfigEntityType = 4
	ConfigEntityType_CONFIG_ENTITY_TYPE_ROUTING_TABLE      ConfigEntityType = 5
	ConfigEntityType_CONFIG_ENTITY_TYPE_NUMBER_RANGE       ConfigEntityType = 6
	ConfigEntityType_CONFIG_ENTITY_TYPE_PARTNER            ConfigEntityType = 7
	ConfigEntityType_CONFIG_ENTITY_TYPE_OPERATOR           ConfigEntityType = 8
	ConfigEntityType_CONFIG_ENTITY_TYPE_SUBSCRIBER_CONSENT ConfigEntityType = 9
	// luminous-hugging-charm.md, BACKOFFICE_DESIGN_SPEC.md Экран 32 —
	// категории сообщений перестают быть фиксированным словарём
	// (SERVICE/TRANSACTION/ADVERTISING/UNTEMPLATED/BLOCKED, раньше жили
	// только как соглашение в документации) и становятся управляемой
	// сущностью: name/regex/count_in_cdr. policy_template.category и
	// billing_tariff.price_per_segment остаются свободной строкой без
	// изменений — этот entity_type добавляет слой управления/метаданных,
	// не новую валидацию в live-пайплайне.
	ConfigEntityType_CONFIG_ENTITY_TYPE_CATEGORY ConfigEntityType = 10
	// BACKOFFICE_DESIGN_SPEC.md Экран 23 — CTN (termination number),
	// привязка (partner_id, category) -> ctn/service_name для офлайн
	// телеком-биллинга (CDR-экспорт, см. BACKOFFICE_ROADMAP.md — сама
	// генерация CDR не реализована, только эта справочная сущность).
	ConfigEntityType_CONFIG_ENTITY_TYPE_CTN ConfigEntityType = 11
	// BACKOFFICE_DESIGN_SPEC.md Экран 36 "Pattern Placeholders" — именованные
	// переменные (name/regex) для использования внутри policy_template.
	// Реестр сам по себе — версионируемая справочная сущность (этот
	// entity_type); реальное использование внутри движка матчинга
	// (policy-service/src/template_matching.rs) — отдельное изменение движка,
	// не покрывается одним этим entity_type.
	ConfigEntityType_CONFIG_ENTITY_TYPE_PATTERN_PLACEHOLDER ConfigEntityType = 12
	// BACKOFFICE_DESIGN_SPEC.md Экран 41 "Guides" — статический справочный
	// контент внутри админки (title/body_markdown/category), тот же
	// версионируемый (draft/publish через ArchiveVersion) паттерн, что
	// остальные entity_type здесь, не отдельная CMS-таблица.
	ConfigEntityType_CONFIG_ENTITY_TYPE_GUIDE ConfigEntityType = 13
)

